CREATE OR REPLACE FUNCTION public.confirm_weekly_checkin_context(p_checkin_id uuid, p_expected_revision integer, p_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_athlete_id uuid := (select auth.uid());
  v_checkin public.weekly_checkins;
  v_context public.weekly_checkin_contexts;
  v_restriction jsonb;
  v_external jsonb;
  v_status text;
  v_allowed text;
  v_choice text;
  v_now timestamptz := statement_timestamp();
begin
  select * into v_checkin
  from public.weekly_checkins
  where id = p_checkin_id and athlete_id = v_athlete_id
  for update;
  if not found then
    raise exception 'weekly check-in not found' using errcode = 'P0002';
  end if;
  if v_checkin.status <> 'open' then
    raise exception 'check-in is already completed' using errcode = 'PT409';
  end if;
  if v_checkin.context_revision <> p_expected_revision then
    raise exception 'check-in context is stale' using errcode = 'PT409';
  end if;
  select * into v_context
  from public.weekly_checkin_contexts
  where checkin_id = p_checkin_id
    and athlete_id = v_athlete_id
    and revision = p_expected_revision
    and state = 'draft'
  for update;
  if not found or v_context.fingerprint <> p_fingerprint then
    raise exception 'check-in context is stale' using errcode = 'PT409';
  end if;
  if exists (
    select 1
    from public.injury_restrictions active
    where active.athlete_id = v_athlete_id
      and active.cleared_at is null
      and not exists (
        select 1
        from jsonb_array_elements(v_context.payload -> 'restrictions') item
        where item ->> 'discipline' = active.discipline
      )
  ) then
    raise exception 'active restriction review is missing' using errcode = 'PT409';
  end if;
  perform set_config('start23.checkin_write', 'on', true);
  update public.weekly_checkin_contexts
  set state = 'confirmed', confirmed_at = v_now
  where id = v_context.id and athlete_id = v_athlete_id;

  for v_restriction in
    select value from jsonb_array_elements(v_context.payload -> 'restrictions')
  loop
    v_status := v_restriction ->> 'status';
    v_allowed := case
      when v_status = 'none' then 'unrestricted'
      when v_status = 'self_reported_limited' then 'low_only'
      else 'none'
    end;
    v_choice := v_restriction ->> 'athlete_plan_choice';
    update public.injury_restrictions
    set cleared_at = v_now
    where athlete_id = v_athlete_id
      and discipline = v_restriction ->> 'discipline'
      and cleared_at is null;
    if v_status <> 'none' then
      insert into public.injury_restrictions (
        athlete_id, context_id, discipline, status, allowed_intensity, source,
        start_at, review_at, professional_advice, professional_advice_at,
        athlete_plan_choice, confirmed_at
      ) values (
        v_athlete_id,
        v_context.id,
        v_restriction ->> 'discipline',
        v_status,
        v_allowed,
        v_restriction ->> 'source',
        v_now,
        v_now + interval '7 days',
        nullif(v_restriction ->> 'professional_advice', ''),
        nullif(v_restriction ->> 'professional_advice_at', '')::timestamptz,
        v_choice,
        v_now
      );
    end if;
  end loop;

  for v_external in
    select value from jsonb_array_elements(v_context.payload -> 'external_activities')
  loop
    insert into public.planned_external_activities (
      athlete_id, context_id, week_start, name, discipline, scheduled_at,
      timezone, duration_minutes, strenuous, recurring
    ) values (
      v_athlete_id,
      v_context.id,
      v_checkin.week_start,
      v_external ->> 'name',
      v_external ->> 'discipline',
      (v_external ->> 'scheduled_at')::timestamptz,
      v_checkin.timezone,
      (v_external ->> 'duration_minutes')::numeric,
      (v_external ->> 'strenuous')::boolean,
      (v_external ->> 'recurring')::boolean
    );
  end loop;
  update public.weekly_checkins
  set updated_at = v_now
  where id = p_checkin_id and athlete_id = v_athlete_id;
  return public.get_weekly_checkin(p_checkin_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_swipe_week_draft(p_athlete_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_existing public.swipe_week_drafts;
  v_result public.swipe_week_drafts;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role' then
    raise exception 'trusted backend authorization required' using errcode = '42501';
  end if;
  if p_athlete_id is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'invalid swipe draft input' using errcode = '23514';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      p_athlete_id::text || ':swipe:' || (p_payload ->> 'week_start'), 0
    )
  );
  select * into v_existing
  from public.swipe_week_drafts
  where athlete_id = p_athlete_id
    and week_start = (p_payload ->> 'week_start')::date
    and state in ('collecting', 'placement')
  for update;

  if found
     and v_existing.context_fingerprint = p_payload ->> 'context_fingerprint' then
    return to_jsonb(v_existing) - 'athlete_id';
  end if;

  perform set_config('start23.critical_write', 'on', true);
  if v_existing.id is not null then
    update public.swipe_week_drafts
    set state = 'cancelled', current_template_id = null,
        updated_at = statement_timestamp(), revision = revision + 1
    where id = v_existing.id and athlete_id = p_athlete_id;
  end if;

  insert into public.swipe_week_drafts (
    athlete_id, plan_id, initial_plan_request_id, base_plan_revision,
    context_plan_revision, week_start, timezone, available_dates,
    availability_source, confirmed_injuries, low_only_disciplines,
    input_fingerprint, context_fingerprint, ruleset_version,
    target_workout_count, target_composition, accepted_template_ids,
    passed_template_ids, current_template_id, decision_history, placements,
    state
  ) values (
    p_athlete_id, nullif(p_payload ->> 'plan_id', '')::uuid,
    (p_payload ->> 'initial_plan_request_id')::uuid,
    (p_payload ->> 'base_plan_revision')::integer,
    nullif(p_payload ->> 'context_plan_revision', '')::integer,
    (p_payload ->> 'week_start')::date, p_payload ->> 'timezone',
    array(select jsonb_array_elements_text(p_payload -> 'available_dates'))::date[],
    p_payload ->> 'availability_source',
    array(select jsonb_array_elements_text(p_payload -> 'confirmed_injuries')),
    array(select jsonb_array_elements_text(p_payload -> 'low_only_disciplines')),
    p_payload ->> 'input_fingerprint', p_payload ->> 'context_fingerprint',
    p_payload ->> 'ruleset_version',
    (p_payload ->> 'target_workout_count')::integer,
    p_payload -> 'target_composition', '{}', '{}',
    nullif(p_payload ->> 'current_template_id', '')::uuid, '[]', '{}',
    p_payload ->> 'state'
  ) returning * into v_result;
  return to_jsonb(v_result) - 'athlete_id';
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_zone_profile(p_discipline text, p_setup_method text, p_metric_kind text, p_metric_value numeric, p_boundaries jsonb, p_requires_review boolean, p_review_reason text, p_ruleset_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_athlete_id uuid := (select auth.uid());
  v_active_id uuid;
  v_profile_id uuid;
  v_proposal_id uuid;
  v_version integer;
  v_status text;
begin
  if v_athlete_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  if jsonb_typeof(p_boundaries) <> 'array'
     or jsonb_array_length(p_boundaries) <> 5 then
    raise exception 'exactly five boundaries are required'
      using errcode = '23514';
  end if;
  if p_setup_method = 'manual' then
    if p_metric_kind is null or p_metric_value is null then
      raise exception 'manual zones require a metric'
        using errcode = '23514';
    end if;
    if not (
      (p_discipline = 'swim' and p_metric_kind = 'swim_css_seconds_per_100m')
      or (
        p_discipline = 'bike'
        and p_metric_kind in (
          'bike_ftp_watts',
          'bike_threshold_heart_rate_bpm'
        )
      )
      or (
        p_discipline = 'run'
        and p_metric_kind in (
          'run_threshold_pace_seconds_per_km',
          'run_lthr_bpm'
        )
      )
    ) then
      raise exception 'zone metric does not match discipline'
        using errcode = '23514';
    end if;
  elsif p_setup_method = 'fallback' then
    if p_discipline = 'swim'
       or p_metric_kind is not null
       or p_metric_value is not null then
      raise exception 'fallback is heart-rate-only for bike or run'
        using errcode = '23514';
    end if;
  else
    raise exception 'unsupported zone setup method'
      using errcode = '23514';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_athlete_id::text || ':' || p_discipline, 0)
  );
  perform set_config('start23.critical_write', 'on', true);

  select id into v_active_id
  from public.zone_profile_versions
  where athlete_id = v_athlete_id
    and discipline = p_discipline
    and status = 'active';

  select coalesce(max(version), 0) + 1 into v_version
  from public.zone_profile_versions
  where athlete_id = v_athlete_id
    and discipline = p_discipline;

  v_status := case when v_active_id is null then 'active' else 'pending' end;

  insert into public.zone_profile_versions (
    athlete_id,
    discipline,
    version,
    setup_method,
    status,
    validated,
    fallback_active,
    needs_testing,
    requires_review,
    review_reason,
    ruleset_version,
    effective_from
  )
  values (
    v_athlete_id,
    p_discipline,
    v_version,
    p_setup_method,
    v_status,
    p_setup_method = 'manual',
    p_setup_method = 'fallback',
    p_setup_method = 'fallback',
    p_requires_review,
    p_review_reason,
    p_ruleset_version,
    case when v_status = 'active' then statement_timestamp() else null end
  )
  returning id into v_profile_id;

  if p_metric_kind is not null then
    insert into public.zone_metrics (
      zone_profile_id,
      athlete_id,
      metric_kind,
      value
    )
    values (
      v_profile_id,
      v_athlete_id,
      p_metric_kind,
      p_metric_value
    );
  elsif p_setup_method <> 'fallback' then
    raise exception 'manual zones require a metric'
      using errcode = '23514';
  end if;

  insert into public.zone_boundaries (
    zone_profile_id,
    athlete_id,
    zone_number,
    lower_value,
    upper_value
  )
  select
    v_profile_id,
    v_athlete_id,
    boundary.zone_number,
    boundary.lower_value,
    boundary.upper_value
  from jsonb_to_recordset(p_boundaries) as boundary(
    zone_number smallint,
    lower_value numeric,
    upper_value numeric
  );

  if (
    select count(distinct zone_number)
    from public.zone_boundaries
    where zone_profile_id = v_profile_id
  ) <> 5 then
    raise exception 'zones 1 through 5 are required'
      using errcode = '23514';
  end if;

  if p_setup_method = 'manual'
     and p_metric_kind in (
       'swim_css_seconds_per_100m',
       'run_threshold_pace_seconds_per_km'
     )
     and (
       p_metric_value <> trunc(p_metric_value)
       or exists (
         select 1
         from public.zone_boundaries
         where zone_profile_id = v_profile_id
           and (
             lower_value <> trunc(lower_value)
             or upper_value <> trunc(upper_value)
           )
       )
     ) then
    raise exception 'pace zones require whole seconds'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from public.zone_boundaries current_zone
    join public.zone_boundaries previous_zone
      on previous_zone.zone_profile_id = current_zone.zone_profile_id
      and previous_zone.zone_number = current_zone.zone_number - 1
    where current_zone.zone_profile_id = v_profile_id
      and (
        (
          p_setup_method = 'manual'
          and p_metric_kind in (
            'swim_css_seconds_per_100m',
            'run_threshold_pace_seconds_per_km'
          )
          and previous_zone.lower_value <> current_zone.upper_value
        )
        or (
          (
            p_setup_method = 'fallback'
            or p_metric_kind not in (
              'swim_css_seconds_per_100m',
              'run_threshold_pace_seconds_per_km'
            )
          )
          and previous_zone.upper_value <> current_zone.lower_value
        )
      )
  ) then
    raise exception 'zone boundaries must be contiguous'
      using errcode = '23514';
  end if;

  if v_status = 'pending' then
    insert into public.change_proposals (
      athlete_id,
      kind,
      target_zone_profile_id,
      base_zone_profile_id,
      reason_codes,
      public_explanation,
      ruleset_version
    )
    values (
      v_athlete_id,
      'zone_update',
      v_profile_id,
      v_active_id,
      array['zone_replacement_requires_approval'],
      'A new zone version is ready for your review. Your active zones have not changed.',
      p_ruleset_version
    )
    returning id into v_proposal_id;
  end if;

  return jsonb_build_object(
    'profile_id', v_profile_id,
    'version', v_version,
    'status', v_status,
    'proposal_id', v_proposal_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_swipe_week_draft(p_athlete_id uuid, p_draft_id uuid, p_expected_revision bigint, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_current public.swipe_week_drafts;
  v_result public.swipe_week_drafts;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role' then
    raise exception 'trusted backend authorization required' using errcode = '42501';
  end if;
  select * into v_current
  from public.swipe_week_drafts
  where id = p_draft_id and athlete_id = p_athlete_id
  for update;
  if not found then
    raise exception 'swipe draft not found' using errcode = 'P0002';
  end if;
  if v_current.revision <> p_expected_revision then
    raise exception 'swipe draft is stale' using errcode = 'PT409';
  end if;
  if v_current.state not in ('collecting', 'placement') then
    raise exception 'swipe draft is closed' using errcode = 'PT409';
  end if;
  if p_payload ->> 'context_fingerprint' <> v_current.context_fingerprint then
    raise exception 'swipe draft context changed' using errcode = 'PT409';
  end if;

  perform set_config('start23.critical_write', 'on', true);
  update public.swipe_week_drafts set
    accepted_template_ids = array(
      select jsonb_array_elements_text(p_payload -> 'accepted_template_ids')
    )::uuid[],
    passed_template_ids = array(
      select jsonb_array_elements_text(p_payload -> 'passed_template_ids')
    )::uuid[],
    current_template_id = nullif(p_payload ->> 'current_template_id', '')::uuid,
    decision_history = p_payload -> 'decision_history',
    placements = p_payload -> 'placements',
    state = p_payload ->> 'state',
    plan_id = case
      when p_payload ->> 'state' = 'submitted'
        then (p_payload ->> 'plan_id')::uuid
      else plan_id
    end,
    proposal_id = nullif(p_payload ->> 'proposal_id', '')::uuid,
    submitted_at = case
      when p_payload ->> 'state' = 'submitted' then statement_timestamp()
      else null
    end,
    revision = revision + 1,
    updated_at = statement_timestamp()
  where id = p_draft_id and athlete_id = p_athlete_id
  returning * into v_result;
  return to_jsonb(v_result) - 'athlete_id';
end;
$function$
